<template>
  <section class="pc-panel">
    <h2>PAI 项目规则与明确提供的 import</h2>
    <el-alert title="中心按个人 PAI、根 PAI、.paicli/PAI、PAI.local、.paicli/PAI.local 顺序冻结来源。import 最多解析 3 层，派生上下文合计 24000 字符；原文和摘要保留。登记资料不能扩大执行权限。" type="info" :closable="false" />
    <el-alert v-if="!canRead" title="当前角色没有知识读取权限。" type="info" :closable="false" />
    <template v-else><div class="pc-actions"><el-button :loading="loading" @click="load">刷新规则元数据</el-button><el-button v-hasPermi="['paicli:knowledge:manage']" @click="create">登记原始规则</el-button></div><el-table :data="rules"><el-table-column label="来源层" min-width="200"><template #default="{row}">{{layerName(row.layer)}}</template></el-table-column><el-table-column prop="sourcePath" label="原相对路径" min-width="220" /><el-table-column prop="version" label="版本" width="80" /><el-table-column label="状态" width="100"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column prop="sha256" label="原文摘要" min-width="220" /><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-hasPermi="['paicli:context:raw']" link @click="read(row)">原文与来源</el-button></template></el-table-column></el-table><el-empty v-if="!loading && !rules.length && !localError" description="尚未登记规则，沿用已有任务资料" /></template>
    <el-alert v-if="localError || error" :title="localError || error" type="error" :closable="false" />
    <el-dialog v-model="open" :title="form.id?'原始规则与当前版本':'登记明确提供的 PAI 来源'" width="850px" class="pc-dialog"><p v-if="registeredSource" class="pc-muted">原条目 {{registeredSource.id}} · 版本 {{registeredSource.version}} · 所有者 {{registeredSource.ownerId || '未提供'}} · {{sourceName(registeredSource.source)}}<template v-if="registeredSource.importBatchId"> · 原导入批次 {{registeredSource.importBatchId}}</template></p><el-form label-width="130px" :disabled="busy"><el-form-item label="来源层"><el-select v-model="form.layer" :disabled="!!form.id" @change="changeLayer"><el-option v-for="(label,key) in layers" :key="key" :label="label" :value="key" /></el-select></el-form-item><el-form-item label="原相对路径"><el-input v-model="form.sourcePath" :readonly="!canEditForm" /></el-form-item><el-form-item label="原文来源"><el-radio-group v-model="sourceMode" :disabled="!canEditForm"><el-radio value="TEXT">直接提供原文</el-radio><el-radio value="ARTIFACT">已上传的中心产物</el-radio></el-radio-group></el-form-item><el-form-item v-if="sourceMode==='TEXT'" label="原始正文"><el-input v-model="form.content" type="textarea" :rows="9" :readonly="!canEditForm" /></el-form-item><el-form-item v-else label="正文产物 ID"><el-input v-model="form.contentArtifactId" :readonly="!canEditForm" placeholder="当前获授权、同工作区的 UTF-8 文本产物数字 ID" /></el-form-item><el-form-item label="imports 来源"><el-input v-model="importsText" type="textarea" :rows="6" :readonly="!canEditForm" placeholder='[{"path":"rules/style.md","content":"原文"}] 或 contentArtifactId' /></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled" :disabled="!canEditForm" /></el-form-item></el-form><section v-if="canEditForm && checkPermi(['paicli:artifact:write'])" class="pc-panel"><h3>上传明确提供的 UTF-8 原文</h3><el-radio-group v-model="uploadTarget" :disabled="busy"><el-radio value="MAIN">当前来源正文</el-radio><el-radio value="IMPORT">新增一项 import 来源</el-radio></el-radio-group><el-input v-if="uploadTarget==='IMPORT'" v-model="uploadImportPath" :disabled="busy" placeholder="明确的 import 相对路径，例如 rules/style.md" /><input type="file" accept=".md,.txt,text/markdown,text/plain" :disabled="busy" @change="selectSourceFile" /><p v-if="sourceFile" class="pc-muted">{{sourceFile.name}} · {{sourceFile.size}}B</p><el-button v-hasPermi="['paicli:artifact:write']" :disabled="!sourceFile || !workspaceId || (uploadTarget==='IMPORT'&&!uploadImportPath.trim())" :loading="busy" @click="uploadSource">上传原文并引用真实产物</el-button><p v-if="uploadedSource" class="pc-muted">已上传：{{uploadedSource.fileName}} · 产物 {{uploadedSource.id}} · SHA {{uploadedSource.sha256}} · {{uploadedSource.size}}B。来源规则尚须按版本保存。</p></section><p class="pc-muted">直接正文最多 1 MiB UTF-8；较大原文可在此独立上传（最多 50 MiB）后引用中心产物。import 必须逐个明确提供，界面和中心不会扫描本机路径。</p><el-alert v-for="warning in warnings" :key="warning" :title="warning" type="warning" :closable="false" /><el-alert v-if="form.id && !canEditForm" title="中心当前仅允许读取此规则。更新须同时满足原归属与来源范围、中心可编辑条件和知识管理权限，不能另行登记覆盖既有来源层。" type="info" :closable="false" /><section v-if="registeredSource"><PaiSourceDownload v-if="registeredSource.contentArtifactId" label="已登记正文来源" :path="registeredSource.sourcePath" :artifact-id="registeredSource.contentArtifactId" :owner-id="registeredSource.ownerId" :workspace-id="registeredSource.scope==='PROJECT'?registeredSource.workspaceId:undefined" :sha256="registeredSource.sha256" :artifact="registeredSource.contentArtifact" /><template v-for="item in registeredSource.imports" :key="item.path"><PaiSourceDownload v-if="item.contentArtifactId" label="已登记 import 来源" :path="item.path" :artifact-id="item.contentArtifactId" :owner-id="registeredSource.ownerId" :workspace-id="registeredSource.scope==='PROJECT'?registeredSource.workspaceId:undefined" :sha256="item.sha256" :artifact="item.contentArtifact" /></template></section><PaiSourceDownload v-if="uploadedSource" label="本次明确上传的原文（规则尚须保存）" :path="uploadedSource.fileName" :artifact-id="uploadedSource.id" :owner-id="uploadedSource.ownerId" :workspace-id="uploadedSource.workspaceId" :sha256="uploadedSource.sha256" :artifact="uploadedSource" /><el-collapse v-if="resolved"><el-collapse-item title="当前派生正文（保留原文独立核对）"><pre class="pc-pre">{{safeText(resolved)}}</pre></el-collapse-item></el-collapse><el-alert v-if="localError || error" :title="localError || error" type="error" :closable="false" /><template #footer><el-button :disabled="busy" @click="open=false">关闭</el-button><el-button v-if="canEditForm" v-hasPermi="['paicli:knowledge:manage']" type="primary" :loading="busy" :disabled="!form.sourcePath || (sourceMode==='TEXT'?!form.content.trim():!/^\d+$/.test(form.contentArtifactId))" @click="save">按当前版本保存来源</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {checkPermi} from '@/utils/permission'
import {getProjectRule,listProjectRules,saveProjectRule,uploadPaiSource} from '@/api/paicli/projectRules'
import type {PcProjectRule,PcRuleLayer,PcSourceArtifact} from '@/types/paicli'
import {errorText,operationKeys,safeText} from '../model'
import {parseRuleImports} from '../shared/registrationInputs'
import {useOperations} from '../useOperations'
import useUserStore from '@/store/modules/user'
import PaiSourceDownload from './PaiSourceDownload.vue'
const props=defineProps<{workspaceId:string}>(),canRead=computed(()=>checkPermi(['paicli:knowledge:read'])),canManage=computed(()=>checkPermi(['paicli:knowledge:manage'])),{busy,error,run}=useOperations(),keys=operationKeys(),rules=ref<PcProjectRule[]>([]),loading=ref(false),localError=ref(''),open=ref(false),sourceMode=ref<'TEXT'|'ARTIFACT'>('TEXT'),importsText=ref('[]'),warnings=ref<string[]>([]),resolved=ref(''),editable=ref(true),registeredSource=ref<PcProjectRule>()
const layers:Record<PcRuleLayer,string>={USER_PAI:'当前用户个人 PAI',ROOT_PAI:'项目根 PAI.md',PAICLI_PAI:'.paicli/PAI.md',LOCAL_PAI:'PAI.local.md',PAICLI_LOCAL_PAI:'.paicli/PAI.local.md'},paths:Record<PcRuleLayer,string>={USER_PAI:'user/PAI.md',ROOT_PAI:'PAI.md',PAICLI_PAI:'.paicli/PAI.md',LOCAL_PAI:'PAI.local.md',PAICLI_LOCAL_PAI:'.paicli/PAI.local.md'}
const sourceFile=ref<File>(),uploadTarget=ref<'MAIN'|'IMPORT'>('MAIN'),uploadImportPath=ref(''),uploadedSource=ref<PcSourceArtifact>();let editorGeneration=0
function clearUpload(){editorGeneration++;sourceFile.value=undefined;uploadedSource.value=undefined;uploadTarget.value='MAIN';uploadImportPath.value=''}
const form=reactive({id:'',version:0,layer:'ROOT_PAI' as PcRuleLayer,sourcePath:'PAI.md',content:'',contentArtifactId:'',enabled:true}),canEditForm=computed(()=>canManage.value&&editable.value);let generation=0
async function load(){const id=props.workspaceId,g=++generation;if(!id||!canRead.value)return;loading.value=true;localError.value='';try{const response=await listProjectRules(id);if(g===generation&&id===props.workspaceId)rules.value=response.data}catch(cause){if(g===generation)localError.value=errorText(cause)}finally{if(g===generation)loading.value=false}}
function sourceName(source?:string){return source==='IMPORTED_PROJECT_RULE'?'历史导入规则':source==='PROJECT_MEMORY'?'初始化项目规则':source==='PAI_RULE'?'明确审阅的 PAI 来源':'中心登记来源'}
function layerName(layer:PcRuleLayer){return layers[layer] || layer}
function changeLayer(){if(!form.id)form.sourcePath=paths[form.layer]}
function create(){if(!canManage.value||busy.value)return;clearUpload();editable.value=true;registeredSource.value=undefined;Object.assign(form,{id:'',version:0,layer:'ROOT_PAI',sourcePath:'PAI.md',content:'',contentArtifactId:'',enabled:true});sourceMode.value='TEXT';importsText.value='[]';warnings.value=[];resolved.value='';localError.value='';error.value='';open.value=true}
async function read(row:PcProjectRule){if(!checkPermi(['paicli:context:raw'])||busy.value)return;const g=generation;await run(async()=>{const response=await getProjectRule(row.id);if(g!==generation)return;const data=response.data;clearUpload();registeredSource.value=data;editable.value=data.canEdit===true && Object.prototype.hasOwnProperty.call(layers,data.layer);Object.assign(form,{id:data.id,version:data.version,layer:data.layer,sourcePath:data.sourcePath,content:data.originalContent || '',contentArtifactId:data.contentArtifactId || '',enabled:data.enabled});sourceMode.value=data.contentArtifactId?'ARTIFACT':'TEXT';importsText.value=JSON.stringify((data.imports || []).map(item=>({path:item.path,...(item.contentArtifactId?{contentArtifactId:item.contentArtifactId}:{content:item.content})})),null,2);warnings.value=data.warnings || [];resolved.value=data.resolvedContent || data.content || '';localError.value='';open.value=true})}
function selectSourceFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file&&(!file.size||file.size>50*1024*1024)){localError.value='PAI 原文须为非空 UTF-8 文件，最多 50 MiB';sourceFile.value=undefined;return}sourceFile.value=file;localError.value=''}
async function uploadSource(){const file=sourceFile.value;if(!file||!props.workspaceId||!canEditForm.value||!checkPermi(['paicli:artifact:write']))return;const ws=props.workspaceId,g=editorGeneration,target=uploadTarget.value,path=uploadImportPath.value.trim(),owner=String(useUserStore().id ?? '');await run(async()=>{try{let imports=target==='IMPORT'?parseRuleImports(importsText.value):[];if(target==='IMPORT'){parseRuleImports(JSON.stringify([{path,contentArtifactId:'1'}]));if(imports.some(item=>item.path===path))throw new Error('该 import 路径已有来源，请先明确删除或修改原项，未上传覆盖')}const bytes=await file.arrayBuffer();if(bytes.byteLength!==file.size||!bytes.byteLength||bytes.byteLength>50*1024*1024)throw new Error('原文长度改变或超过 50 MiB，未上传');try{new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{throw new Error('原文不是合法 UTF-8，未上传')}const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),value=>value.toString(16).padStart(2,'0')).join('');if(g!==editorGeneration||ws!==props.workspaceId)return;const intent={action:'PAI_SOURCE',workspaceId:ws,name:file.name,sha256:hash,size:file.size};const artifact=(await uploadPaiSource(ws,file,keys.get(intent))).data;if(g!==editorGeneration||ws!==props.workspaceId)return;if(!/^\d+$/.test(artifact.id)||artifact.workspaceId!==ws||!owner||artifact.ownerId!==owner||artifact.purpose!=='PAI_SOURCE'||artifact.sha256!==hash||artifact.size!==file.size)throw new Error('中心原文产物的归属、用途或摘要与本次文件不同，保留原表单未引用');keys.done(intent);uploadedSource.value=artifact;if(target==='MAIN'){form.contentArtifactId=artifact.id;sourceMode.value='ARTIFACT'}else{imports=[...imports,{path,contentArtifactId:artifact.id}];importsText.value=JSON.stringify(imports,null,2)}sourceFile.value=undefined}catch(cause){if(g===editorGeneration)throw cause}})}
async function save(){if(!canEditForm.value)return;try{if(sourceMode.value==='TEXT'&&new TextEncoder().encode(form.content).length>1024*1024)throw new Error('直接原文超过 1 MiB，请使用已上传的中心文本产物');const data={id:form.id || undefined,version:form.version,scope:form.layer==='USER_PAI'?'PERSONAL' as const:'PROJECT' as const,workspaceId:form.layer==='USER_PAI'?undefined:props.workspaceId,layer:form.layer,sourcePath:form.sourcePath,...(sourceMode.value==='ARTIFACT'?{contentArtifactId:form.contentArtifactId}:{content:form.content}),imports:parseRuleImports(importsText.value),enabled:form.enabled};localError.value='';await run(async()=>{await saveProjectRule(data,keys.get(data));keys.done(data);open.value=false;await load()})}catch(cause){localError.value=errorText(cause)}}
watch(()=>props.workspaceId,()=>{clearUpload();generation++;rules.value=[];registeredSource.value=undefined;open.value=false;void load()},{immediate:true});onBeforeUnmount(()=>{editorGeneration++;generation++})
</script>
